class Solution {
public:
    int minDayskVariants(vector<vector<int>>& points,int k) {
        // Any optimum has an integer grid point in the bounding box.
        int ans=INT_MAX;
        for(int x=1;x<=100;++x) for(int y=1;y<=100;++y) {
            vector<int> d;
            for(auto &p:points) d.push_back(abs(x-p[0])+abs(y-p[1]));
            nth_element(d.begin(),d.begin()+k-1,d.end());
            ans=min(ans,d[k-1]);
        }
        return ans;
    }
};
